/**
 * Render regression corpus.
 *
 * Visual rendering bugs (clipped or blank pages, ignored /Rotate or CropBox,
 * missing fallback fonts, overlay boxes drifting off the glyphs) do not fail a
 * text assertion. This suite rasterises the audit fixtures at fixed scales,
 * compares the pixels with committed references, and checks the text-layer
 * boxes numerically against the canvas ink.
 *
 * References live in `test/pdf-audit/render/`. They were generated by this
 * file, inspected, and only then committed:
 *
 *   $env:UPDATE_RENDER_REFS='1'
 *   pnpm --filter @pdfshush/pdf-core exec vitest run test/render-regression.test.ts
 *
 * Regenerate only when a deliberate rendering change lands, and look at the
 * images before committing them. The tolerance absorbs antialiasing noise, not
 * a moved or missing glyph.
 */

import { afterAll, describe, expect, it } from 'vitest';
import { createCanvas, loadImage } from '@napi-rs/canvas';

import { configurePdfjsRuntime, loadPdfForRender, resetPdfCache } from '../src/render/pdfjsRuntime.js';
import { renderPageToImage } from '../src/render/renderPage.js';
import { extractTextRuns } from '../src/render/textRuns.js';
import { extractPageLayouts } from '../src/render/textLayout.js';
import type { CanvasFactory, RenderCanvas } from '../src/render/canvas.js';
import type { PageLayout } from '../src/document/types.js';
import type { TextRun } from '../src/render/textRuns.js';
import { flipJob } from '../src/jobs/flip.job.js';
import { testContext } from './fixtures.js';

configurePdfjsRuntime({
  workerSrc: new URL('../node_modules/pdfjs-dist/legacy/build/pdf.worker.mjs', import.meta.url).href,
});

interface NodeFs {
  readFileSync(path: URL): Uint8Array;
  writeFileSync(path: URL, data: Uint8Array): void;
  existsSync(path: URL): boolean;
  mkdirSync(path: URL, options: { recursive: true }): void;
}

function nodeFs(): NodeFs {
  const proc = (
    globalThis as unknown as { process: { getBuiltinModule(name: string): unknown } }
  ).process;
  return proc.getBuiltinModule('node:fs') as NodeFs;
}

/** `process.env` without the Node types (this package compiles with `types: []`). */
function env(name: string): string | undefined {
  const proc = (
    globalThis as unknown as { process: { env?: Record<string, string | undefined> } }
  ).process;
  return proc.env?.[name];
}

const fixture = (name: string) => new URL(`../../../tests/fixtures/pdf-audit/${name}`, import.meta.url);
const reference = (name: string) => new URL(`./pdf-audit/render/${name}.png`, import.meta.url);

function pngFactory(width: number, height: number): RenderCanvas {
  const canvas = createCanvas(width, height);
  return {
    width,
    height,
    context: canvas.getContext('2d'),
    async toBlob(type: string, quality?: number) {
      const buffer =
        type === 'image/jpeg'
          ? await canvas.encode('jpeg', quality ? Math.round(quality * 100) : 90)
          : await canvas.encode('png');
      return new Blob([new Uint8Array(buffer)], { type });
    },
    release() {
      canvas.width = 0;
      canvas.height = 0;
    },
  };
}

const canvasFactory: CanvasFactory = pngFactory;

interface Case {
  id: string;
  file: string;
  page: number;
  /** Render scale; 1 is 1 px per PDF point. */
  scale: number;
}

const CASES: readonly Case[] = [
  { id: 'tiny-1page.p1.s1', file: 'tiny-1page.pdf', page: 1, scale: 1 },
  { id: 'rotated-90.p1.s1', file: 'rotated-90.pdf', page: 1, scale: 1 },
  { id: 'rotated-90.p1.s2', file: 'rotated-90.pdf', page: 1, scale: 2 },
  { id: 'rotated-90.p2.s1', file: 'rotated-90.pdf', page: 2, scale: 1 },
  { id: 'cropbox-offset.p1.s1', file: 'cropbox-offset.pdf', page: 1, scale: 1 },
  { id: 'cropbox-offset.p1.s2', file: 'cropbox-offset.pdf', page: 1, scale: 2 },
  { id: 'nonembedded-rtl-arabic.p1.s1', file: 'nonembedded-rtl-arabic.pdf', page: 1, scale: 1 },
  { id: 'image-only.p1.s1', file: 'image-only.pdf', page: 1, scale: 1 },
  { id: 'acroform.p1.s1', file: 'acroform.pdf', page: 1, scale: 1 },
];

/** Decoded pixels, the part every comparison needs. */
interface Decoded {
  width: number;
  height: number;
  pixels: Uint8ClampedArray;
}

/** One rendered page: encoded PNG plus the decoded pixels for comparison. */
interface Raster extends Decoded {
  data: Uint8Array;
}

async function renderCase(entry: Case): Promise<Raster> {
  const data = new Uint8Array(nodeFs().readFileSync(fixture(entry.file)));
  return renderBytes(data, entry.page, entry.scale);
}

async function renderBytes(data: Uint8Array, pageNumber: number, scale: number): Promise<Raster> {
  const { doc, destroy } = await loadPdfForRender(data);
  try {
    const page = await doc.getPage(pageNumber);
    try {
      const targetWidthPx = Math.round(page.getViewport({ scale: 1 }).width * scale);
      const image = await renderPageToImage(page, {
        targetWidthPx,
        format: 'png',
        canvasFactory,
      });
      const bytes = new Uint8Array(image.data);
      const decoded = await decode(bytes);
      return { data: bytes, width: decoded.width, height: decoded.height, pixels: decoded.pixels };
    } finally {
      page.cleanup();
    }
  } finally {
    await destroy();
  }
}

async function decode(bytes: Uint8Array): Promise<Decoded> {
  const image = await loadImage(bytes);
  const canvas = createCanvas(image.width, image.height);
  const context = canvas.getContext('2d');
  context.drawImage(image, 0, 0);
  const data = context.getImageData(0, 0, image.width, image.height);
  return { width: image.width, height: image.height, pixels: data.data };
}

function isInk(pixels: Uint8ClampedArray, width: number, x: number, y: number): boolean {
  const index = (y * width + x) * 4;
  return (
    pixels[index]! < 245 ||
    pixels[index + 1]! < 245 ||
    pixels[index + 2]! < 245
  );
}

/**
 * Compares a render with its reference.
 *
 * `maxPixelDiff` is the per-channel slack (antialiasing on a different font
 * rasteriser); `maxDiffRatio` is the share of pixels allowed to exceed it.
 */
function compare(actual: Decoded, expected: Decoded): { ratio: number; mean: number } {
  expect([actual.width, actual.height]).toEqual([expected.width, expected.height]);
  let changed = 0;
  let total = 0;
  for (let i = 0; i < actual.pixels.length; i += 4) {
    const dr = Math.abs(actual.pixels[i]! - expected.pixels[i]!);
    const dg = Math.abs(actual.pixels[i + 1]! - expected.pixels[i + 1]!);
    const db = Math.abs(actual.pixels[i + 2]! - expected.pixels[i + 2]!);
    const da = Math.abs(actual.pixels[i + 3]! - expected.pixels[i + 3]!);
    total += dr + dg + db + da;
    if (dr > 12 || dg > 12 || db > 12 || da > 12) changed += 1;
  }
  return { ratio: changed / (actual.width * actual.height), mean: total / actual.pixels.length };
}

/** Fraction of the pixels inside `box` that carry ink. */
function inkRatio(
  raster: Raster,
  box: { x: number; y: number; width: number; height: number },
): number {
  const left = Math.max(0, Math.floor(box.x));
  const top = Math.max(0, Math.floor(box.y));
  const right = Math.min(raster.width - 1, Math.ceil(box.x + box.width));
  const bottom = Math.min(raster.height - 1, Math.ceil(box.y + box.height));
  let ink = 0;
  let total = 0;
  for (let y = top; y <= bottom; y += 1) {
    for (let x = left; x <= right; x += 1) {
      total += 1;
      if (isInk(raster.pixels, raster.width, x, y)) ink += 1;
    }
  }
  return total === 0 ? 0 : ink / total;
}

/** Fraction of the ink in `box` expanded by `pad` that lies inside `box`. */
function inkCoverage(
  raster: Raster,
  box: { x: number; y: number; width: number; height: number },
  pad: number,
): number {
  const left = Math.max(0, Math.floor(box.x - pad));
  const top = Math.max(0, Math.floor(box.y - pad));
  const right = Math.min(raster.width - 1, Math.ceil(box.x + box.width + pad));
  const bottom = Math.min(raster.height - 1, Math.ceil(box.y + box.height + pad));
  let inside = 0;
  let around = 0;
  for (let y = top; y <= bottom; y += 1) {
    for (let x = left; x <= right; x += 1) {
      if (!isInk(raster.pixels, raster.width, x, y)) continue;
      around += 1;
      if (x >= box.x - 0.5 && x <= box.x + box.width + 0.5 && y >= box.y - 0.5 && y <= box.y + box.height + 0.5) {
        inside += 1;
      }
    }
  }
  return around === 0 ? 0 : inside / around;
}

interface Extracted {
  runs: TextRun[];
  layout: PageLayout;
}

async function extractCase(entry: Case): Promise<Extracted> {
  const data = new Uint8Array(nodeFs().readFileSync(fixture(entry.file)));
  const [runs] = await extractTextRuns(data, [entry.page - 1]);
  const [layout] = await extractPageLayouts(data, { pageIndexes: [entry.page - 1] });
  return { runs: runs ?? [], layout: layout! };
}

afterAll(async () => {
  await resetPdfCache();
});

describe('render regression', () => {
  for (const entry of CASES) {
    it(`renders ${entry.id} as committed`, async () => {
      nodeFs().mkdirSync(new URL('./pdf-audit/render/', import.meta.url), { recursive: true });
      const actual = await renderCase(entry);
      // White pages are the classic "blank render" symptom: a reference that
      // is blank would pass every other pixel assertion below.
      const ink = countInk(actual);
      expect(ink).toBeGreaterThan(0);

      if (env('UPDATE_RENDER_REFS') === '1') {
        nodeFs().writeFileSync(reference(entry.id), actual.data);
        return;
      }

      const expectedPath = reference(entry.id);
      expect(nodeFs().existsSync(expectedPath), `missing reference ${entry.id}`).toBe(true);
      const expected = await decode(new Uint8Array(nodeFs().readFileSync(expectedPath)));
      const { ratio, mean } = compare(actual, expected);
      expect(ratio, `${entry.id}: ${Math.round(ratio * 1000) / 10}% of pixels changed`).toBeLessThan(0.004);
      expect(mean, `${entry.id}: mean channel difference`).toBeLessThan(1.5);
    });
  }

  it('renders a flipped annotation as page content', async () => {
    const source = new Uint8Array(nodeFs().readFileSync(fixture('annotations.pdf')));
    const output = await flipJob.run(
      { files: [{ name: 'annotations.pdf', data: source }], options: { horizontal: true } },
      testContext(),
    );
    expect(output.warnings?.join(' ')).toMatch(/flattened \d+ annotation/i);
    const actual = await renderBytes(new Uint8Array(output.data), 1, 1);
    expect(countInk(actual)).toBeGreaterThan(0);

    const id = 'flip-annotations.p1.s1';
    if (env('UPDATE_RENDER_REFS') === '1') {
      nodeFs().writeFileSync(reference(id), actual.data);
      return;
    }
    const expectedPath = reference(id);
    expect(nodeFs().existsSync(expectedPath), `missing reference ${id}`).toBe(true);
    const expected = await decode(new Uint8Array(nodeFs().readFileSync(expectedPath)));
    const { ratio, mean } = compare(actual, expected);
    expect(ratio, `${id}: ${Math.round(ratio * 1000) / 10}% of pixels changed`).toBeLessThan(0.004);
    expect(mean, `${id}: mean channel difference`).toBeLessThan(1.5);

    // The highlight was on page 1 around y=700..718 (PDF space -> top of the
    // raster); the painted copy must leave ink where the live annotation was.
    expect(inkRatio(actual, { x: 72, y: 842 - 718, width: 240, height: 18 })).toBeGreaterThan(0.05);
  }, 60_000);

  it('keeps the text layer on the glyphs it describes', async () => {
    for (const entry of CASES) {
      if (entry.scale !== 1) continue;
      const { runs, layout } = await extractCase(entry);
      if (layout.paragraphs.length === 0) continue; // image-only
      const raster = await renderCase(entry);

      for (const paragraph of layout.paragraphs) {
        // The paragraph box is what the text layer paints. Ink outside it means
        // the layer and the raster do not share a coordinate frame.
        // A run may legitimately overhang the page edge (content is clipped by
        // the viewer, e.g. the RTL fixture whose advance is wider than the
        // page). Its origin must still be on the page, and the coverage check
        // below proves the box is on the ink.
        expect(paragraph.bbox.x).toBeGreaterThanOrEqual(0);
        expect(paragraph.bbox.y).toBeGreaterThanOrEqual(0);
        expect(paragraph.bbox.x).toBeLessThan(raster.width);
        expect(paragraph.bbox.y).toBeLessThan(raster.height);
        const painted = inkRatio(raster, paragraph.bbox);
        if (painted > 0.5) {
          // White text on a filled rectangle (the rotated fixture): the
          // paragraph box is covered by the background, so coverage of
          // non-white ink says nothing about where the glyphs are. The glyphs
          // are the non-ink pixels -- an empty box would be fully painted.
          expect(painted).toBeLessThan(0.98);
          continue;
        }
        expect(
          inkCoverage(raster, paragraph.bbox, 2),
          `${entry.id}: paragraph "${paragraph.text.slice(0, 30)}" is off the glyphs`,
        ).toBeGreaterThan(0.8);
      }

      // The click-to-replace run boxes come from a different extractor than the
      // paragraph model; they must land on the same line.
      for (const run of runs) {
        const paragraph = layout.paragraphs.find((candidate) => candidate.text.includes(run.text.trim()));
        if (!paragraph) continue;
        // The run box is the ascent/descent band; the paragraph box is glyph
        // ink. Their edges differ by at most the metric gap (~0.18em), so the
        // slack follows the font size instead of a fixed pixel count.
        const slack = Math.max(4, paragraph.typography.fontSize * 0.3);
        expect(Math.abs(run.x - paragraph.bbox.x)).toBeLessThanOrEqual(slack);
        expect(Math.abs(run.y - paragraph.bbox.y)).toBeLessThanOrEqual(slack);
        // Along the baseline the two boxes must agree. A vertical run's
        // cross-axis extent includes the ascent/descent band, which the
        // paragraph's ink box does not, so width is only comparable here.
        if (run.horizontal) {
          expect(Math.abs(run.width - paragraph.bbox.width)).toBeLessThanOrEqual(4);
        }
      }
    }
  }, 60_000);

  // PDF-RENDER-003, needs decision: pdf.js cannot substitute a font program
  // for a non-embedded CID font when `disableFontFace` is forced on (a worker
  // has no FontFaceSet). The fixture's text extracts correctly but every
  // raster (editor preview, pdf-to-images, grayscale, OCR) paints five .notdef
  // boxes instead. The fix needs an embeddable CJK fallback font, which is a
  // licensing/size decision, so this asserts the desired behaviour instead.
  it.fails('renders non-embedded CJK glyphs instead of .notdef boxes (PDF-RENDER-003)', async () => {
    const entry: Case = { id: 'nonembedded-cjk', file: 'nonembedded-cjk.pdf', page: 1, scale: 2 };
    const { layout } = await extractCase({ ...entry, scale: 1 });
    const paragraph = layout.paragraphs.find((candidate) => candidate.text.includes('你好'))!;
    const raster = await renderCase(entry);
    const box = {
      x: paragraph.bbox.x * 2,
      y: paragraph.bbox.y * 2,
      width: paragraph.bbox.width * 2,
      height: paragraph.bbox.height * 2,
    };
    const cells = Math.max(1, Array.from(paragraph.text).filter((char) => !/\s/.test(char)).length);

    // A .notdef box is a hollow rectangle: every ink pixel sits on its
    // perimeter. Real CJK glyphs have strokes inside their own ink box. Count
    // cells whose ink box has an interior, and require most of them.
    let paintedInteriors = 0;
    for (let cell = 0; cell < cells; cell += 1) {
      const left = Math.floor(box.x + (box.width / cells) * cell);
      const right = Math.ceil(box.x + (box.width / cells) * (cell + 1));
      const top = Math.floor(box.y);
      const bottom = Math.ceil(box.y + box.height);
      let minX = right;
      let maxX = left;
      let minY = bottom;
      let maxY = top;
      let ink = 0;
      for (let y = top; y < bottom; y += 1) {
        for (let x = left; x < right; x += 1) {
          if (!isInk(raster.pixels, raster.width, x, y)) continue;
          ink += 1;
          minX = Math.min(minX, x);
          maxX = Math.max(maxX, x);
          minY = Math.min(minY, y);
          maxY = Math.max(maxY, y);
        }
      }
      if (ink === 0) continue;
      // Shrink the glyph's own ink box by 30% on each side. A tofu border is
      // excluded; a real stroke through the middle is not.
      const insetX = Math.max(2, (maxX - minX + 1) * 0.3);
      const insetY = Math.max(2, (maxY - minY + 1) * 0.3);
      let interior = 0;
      for (let y = Math.floor(minY + insetY); y <= Math.ceil(maxY - insetY); y += 1) {
        for (let x = Math.floor(minX + insetX); x <= Math.ceil(maxX - insetX); x += 1) {
          if (isInk(raster.pixels, raster.width, x, y)) interior += 1;
        }
      }
      if (interior > 0) paintedInteriors += 1;
    }
    expect(paintedInteriors).toBeGreaterThanOrEqual(3);
  }, 60_000);
});

function countInk(raster: Raster): number {
  let ink = 0;
  for (let y = 0; y < raster.height; y += 1) {
    for (let x = 0; x < raster.width; x += 1) {
      if (isInk(raster.pixels, raster.width, x, y)) ink += 1;
    }
  }
  return ink;
}

